{
  "name": "@devcxl/opencode-spec",
  "version": "0.2.0",
  "description": "OpenSpec workflow plugin for OpenCode",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/devcxl/opencode-spec.git"
  },
  "homepage": "https://github.com/devcxl/opencode-spec",
  "bugs": {
    "url": "https://github.com/devcxl/opencode-spec/issues"
  },
  "keywords": [
    "opencode",
    "openspec",
    "opencode-plugin",
    "spec-driven-development",
    "ai-coding-agent"
  ],
  "type": "module",
  "main": "./dist/index.js",
  "oc-plugin": [
    "server"
  ],
  "exports": {
    ".": {
      "import": "./dist/index.js"
    },
    "./server": {
      "import": "./dist/index.js"
    },
    "./package.json": "./package.json"
  },
  "files": [
    "dist",
    "assets",
    "README.md"
  ],
  "publishConfig": {
    "registry": "https://registry.npmjs.org/",
    "access": "public"
  },
  "scripts": {
    "build": "tsc -p tsconfig.json",
    "prepublishOnly": "npm test && npm run typecheck && npm run build",
    "typecheck": "tsc -p tsconfig.json --noEmit",
    "test": "vitest run"
  },
  "dependencies": {
    "@opencode-ai/plugin": "^1.3.7",
    "yaml": "^2.8.3"
  },
  "devDependencies": {
    "@types/node": "^24.6.0",
    "typescript": "^5.9.3",
    "vitest": "^3.2.4"
  }
}

{
  "type": "module"
}
